select customer_id, code, amount, row_number() over (partition by customer_id order by created_at desc) rn, sum(amount) over (partition by customer_id order by created_at rows between unbounded preceding and current row) running_amount, lag(amount) over (partition by customer_id order by created_at) previous_amount from order_payoil where created_at >= date '2026-04-01' and deleted = 0 order by customer_id, rn;
